<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= html_escape($title); ?></title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/core@1.4.0/dist/css/tabler.min.css"><style>body{background:#101831;color:#fff}.shell{max-width:850px;margin:auto;padding:30px 16px}.panel{background:#fff;color:#18223b;border-radius:20px;padding:24px}.gear{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}.item{border:2px solid #e2dcf2;border-radius:15px;padding:16px}.item.on{border-color:#7154bd;background:#f1ecff}.icon{font-size:38px}.pill{font-size:11px;background:#7154bd;color:#fff;padding:3px 8px;border-radius:20px}</style></head><body><main class="shell"><a class="text-white" href="<?= base_url('belajar/english-quest'); ?>">← Peta Dunia</a><h1 class="my-3">🎒 Hero Equipment</h1><div class="panel"><p>Senjata memberi bonus XP, armor melindungi nyawa pada setiap adegan ketiga, dan artifact menambah bonus saat adegan boss.</p><div class="gear"><?php foreach($inventory as $item): ?><article class="item <?= !empty($item['is_equipped'])?'on':''; ?>"><div class="icon"><?= html_escape($item['item_icon']); ?></div><b><?= html_escape($item['item_name']); ?></b><small class="d-block text-secondary"><?= html_escape(ucfirst($item['item_type'])); ?> · ×<?= (int)$item['quantity']; ?></small><?php if(in_array($item['item_type'],['weapon','armor','artifact'],true)): ?><?php if(!empty($item['is_equipped'])): ?><span class="pill">DIPAKAI</span><?php else: ?><a class="btn btn-sm btn-primary mt-2" href="<?= base_url('belajar/english-quest/equip/'.(int)$item['id']); ?>">Pakai</a><?php endif; ?><?php endif; ?></article><?php endforeach; ?><?php if(!$inventory): ?><p class="text-secondary">Belum ada item. Menangkan adegan untuk memperoleh loot.</p><?php endif; ?></div></div></main></body></html>
